-- MotoGo24 — katalog míst: doplnění identity ve Wikidatech (wikidata_id)
-- ---------------------------------------------------------------------------
-- Proč: dohledávání fotek (edge fn `backfill-poi-photos`) hledalo „co je do
-- 600 m a jmenuje se podobně". U izolovaných vrcholů to měřeně nenajde NIC
-- (0/20 na náhodném vzorku bezfotkových hor) a občas to přilepí fotku úplně
-- jiného místa — v katalogu jsou například TŘI různé „Liščí hory" a „Medvědí
-- vrch", jehož jmenovec na Wikipedii leží 220 km jinde.
-- S `wikidata_id` se dá sáhnout přímo na IDENTITU bodu: `wdt:P18` té konkrétní
-- entity a pak její kategorie na Commons (`P373` / sitelink `commonswiki`),
-- kde české a slovenské vrcholy fotky většinou mají.
--
-- Párování je konzervativní: shodný normalizovaný název do 250 m NEBO cokoli
-- do 40 m, vždy jen NEJBLIŽŠÍ wikidatová entita k danému bodu. Fotka se doplní
-- jen tam, kde bod žádnou nemá (13 řádků) — existující se nepřepisuje.
-- Idempotentní (opakovaný běh nastaví totéž).

update public.points_of_interest p
   set wikidata_id = v.qid,
       image_url   = coalesce(p.image_url, v.image_url),
       updated_at  = now()
  from (values
